function scheduleReconnect(source){
  if(reconnectTimer||source!==stream)return;
  reconnectTimer=setTimeout(async()=>{
    reconnectTimer=null;if(source!==stream)return;
    try{
      // A restarted local host mints a fresh HttpOnly session. No token enters JS.
      const response=await fetch('/',{credentials:'same-origin',signal:AbortSignal.timeout(5000)});
      if(source!==stream)return;
      if(response.ok){connect();return;}
    }catch{}
    scheduleReconnect(source);
  },2000);
}
function connect(){partialReplies.clear();clearTimeout(reconnectTimer);reconnectTimer=null;stream?.close();view=disconnected(view);render();const next=new EventSource(`/api/events${business?`?business=${encodeURIComponent(business)}`:''}`);stream=next;next.addEventListener('snapshot',event=>{if(stream!==next)return;try{const snapshot=JSON.parse(event.data);lastSeen=Date.now();view=hydrate(view,snapshot,lastSeen);for(const [id]of partialReplies)if(!snapshot.jobs.some(j=>j.id===id&&j.status==='running'))partialReplies.delete(id);business=snapshot.business.id;render();}catch{$('notice').textContent='Invalid snapshot; activity unknown.';view=disconnected(view);render();}});next.addEventListener('model_text',event=>{if(stream!==next)return;try{const update=JSON.parse(event.data);if(update.businessId!==business||typeof update.text!=='string'||update.text.length>1000000||!view.snapshot?.jobs.some(j=>j.id===update.jobId&&j.status==='running'))return;partialReplies.set(update.jobId,update);lastSeen=Date.now();render();}catch{}});next.addEventListener('heartbeat',()=>{if(stream===next)lastSeen=Date.now();});next.onerror=()=>{if(stream!==next)return;view=disconnected(view);render();scheduleReconnect(next);};}
function enterScope(id){if(id!=='hq-station'&&!hq?.profile?.businesses.some(b=>b.id===id))return;if(composerKey)composerDrafts.set(composerKey,$('job-objective').value);business=id;arranging=false;world.arrange(false);$('arrange-floor').textContent='ARRANGE';$('arrange-floor').classList.remove('active');selectedWorkstream=null;composerKey=null;partialReplies.clear();view=initialView();closePanel();$('panel-content').replaceChildren();$('station-inspector').hidden=true;$('notice').textContent='';$('job-objective').value='';world.reset();connect();}
